func TestVersionVectorMerge(t *testing.T) {
	a := VersionVector{"n1": 3, "n2": 1}
	b := VersionVector{"n1": 2, "n2": 5, "n3": 1}
	changed := a.Merge(b)
	if !changed {
		t.Fatal("expected change")
	}
	if a["n1"] != 3 || a["n2"] != 5 || a["n3"] != 1 {
		t.Fatalf("bad merge: %v", a)
	}
}

func TestStoreMergeCausality(t *testing.T) {
	s := NewStore("n1")
	s.Put("k", []byte("v1"))
	remote := Entry{
		Key:   "k",
		Value: []byte("v2"),
		VV:    VersionVector{"n2": 1},
	}
	if !s.MergeRemote(remote) {
		t.Fatal("expected merge")
	}
	got, _ := s.Get("k")
	if string(got.Value) != "v2" {
		t.Fatalf("expected v2, got %s", got.Value)
	}
	// Older remote should be ignored
	old := Entry{
		Key:   "k",
		Value: []byte("v0"),
		VV:    VersionVector{"n2": 0},
	}
	if s.MergeRemote(old) {
		t.Fatal("expected no merge for stale entry")
	}
}

func TestGossipLoopIntegration(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	storeA := NewStore("A")
	storeB := NewStore("B")
	storeA.Put("key", []byte("value"))

	// In-memory transport for testing
	transA := NewMemTransport("A", map[string]string{"B": "B"})
	transB := NewMemTransport("B", map[string]string{"A": "A"})
	transA.peer = transB
	transB.peer = transA

	loopA := NewGossipLoop(storeA, transA, "A", 10*time.Millisecond, slog.Default())
	loopB := NewGossipLoop(storeB, transB, "B", 10*time.Millisecond, slog.Default())

	go loopA.Run(ctx)
	go loopB.Run(ctx)
	go loopA.Serve(ctx)
	go loopB.Serve(ctx)

	time.Sleep(100 * time.Millisecond)

	got, ok := storeB.Get("key")
	if !ok {
		t.Fatal("key not propagated")
	}
	if string(got.Value) != "value" {
		t.Fatalf("wrong value: %s", got.Value)
	}
}

// MemTransport is a minimal in-memory transport for tests.
type MemTransport struct {
	id   string
	peers map[string]string
	peer *MemTransport
	recv chan GossipMessage
}

func NewMemTransport(id string, peers map[string]string) *MemTransport {
	return &MemTransport{id: id, peers: peers, recv: make(chan GossipMessage, 16)}
}

func (m *MemTransport) Send(ctx context.Context, peer string, msg GossipMessage) error {
	if m.peer == nil {
		return ErrUnknownPeer
	}
	select {
	case m.peer.recv <- msg:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (m *MemTransport) Receive(ctx context.Context) (GossipMessage, error) {
	select {
	case msg := <-m.recv:
		return msg, nil
	case <-ctx.Done():
		return GossipMessage{}, ctx.Err()
	}
}

func (m *MemTransport) Peers() []string {
	out := make([]string, 0, len(m.peers))
	for k := range m.peers {
		out = append(out, k)
	}
	return out
}

func (m *MemTransport) Close() error { return nil }